const transcripts = items[0]?.json?.Data?.transcripts;

if (!transcripts || typeof transcripts !== 'object') {
  throw new Error("No transcripts found.");
}

// Récupère automatiquement la première langue disponible
const firstLanguage = Object.keys(transcripts)[0];

if (!firstLanguage) {
  throw new Error("No language transcript found.");
}

// Récupère les chunks
const transcriptChunks =
  transcripts[firstLanguage]?.custom ||
  transcripts[firstLanguage]?.custom_transcript ||
  transcripts[firstLanguage]?.transcript ||
  [];

// Vérification
if (!Array.isArray(transcriptChunks)) {
  throw new Error("Transcript chunks not found.");
}

// Combine le texte
const combinedText = transcriptChunks
  .map(chunk => chunk.text || "")
  .join(" ")
  .replace(/\s+/g, " ")
  .trim();

return [
  {
    json: {
      language: firstLanguage,
      combinedTranscript: combinedText
    }
  }
];

return items.map(item => {

  // Sécurisation du champ texte
  const rawText = String(item.json.text || "");

  // Pipeline de nettoyage avancé
  const cleanedText = rawText

    // Remplace \r\n (Windows)
    .replace(/\r\n/g, " ")

    // Remplace \n
    .replace(/\n/g, " ")

    // Remplace \t (tabulations)
    .replace(/\t/g, " ")

    // Supprime espaces multiples
    .replace(/\s+/g, " ")

    // Nettoyage final
    .trim();

  return {
    json: {

      // Texte nettoyé
      cleanedText,

      // Nombre de caractères
      length: cleanedText.length,

      // Nombre de mots
      words: cleanedText.split(" ").filter(Boolean).length

    }
  };

});

return items.map(item => {

  const raw = String(item.json.output || "");

  // Extraction des titres
  const matches = raw.match(/\d+\.\s.*?(?=\n\d+\.|\s*$)/gs) || [];

  // Nettoyage
  const titles = matches.map(title =>
    title
      .replace(/\n/g, " ")
      .replace(/\s+/g, " ")
      .trim()
  );

  return {
    json: {

      // Tableau des titres
      titles,

      // Nombre total
      total_titles: titles.length,

    }
  };

});

return items.map(item => {
  const videoLink = item.json["Video Link"];
  const match = videoLink.match(/(?:v=|\/)([0-9A-Za-z_-]{11})/);

  const videoId = match ? match[1] : null;

  return {
    json: {
      "Video Link": videoLink,
      "video_id": videoId
    }
  };
});
